import React from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet, Alert } from 'react-native';
import { COLORS, SIZES } from '../../constants';
import SimulationProgress from '../../components/SimulationProgress';
import { useSimulation } from '../../context/SimulationContext';

const labelMap = {
  general: 'General Examination',
  cardiovascular: 'Cardiovascular',
  respiratory: 'Respiratory',
  abdominal: 'Abdominal',
  neurological: 'Neurological'
};

const ExaminationScreen = ({ navigation }) => {
  const { selectedCase, examinationsRequested, setExaminationsRequested } = useSimulation();

  if (!selectedCase) {
    return null;
  }

  const areas = selectedCase.examination;

  const toggleArea = areaId => {
    setExaminationsRequested(prev =>
      prev.includes(areaId) ? prev.filter(item => item !== areaId) : [...prev, areaId]
    );
  };

  const handleContinue = () => {
    if (examinationsRequested.length === 0) {
      Alert.alert('Select at least one area', 'Choose at least one examination area before continuing.');
      return;
    }
    navigation.navigate('InitialDiagnosis');
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      <SimulationProgress activeStage="examination" />
      <Text style={styles.title}>Physical Examination</Text>
      <Text style={styles.subtitle}>Choose the areas you want to examine and review the verified findings.</Text>

      {areas.map(area => {
        const selected = examinationsRequested.includes(area.id);
        return (
          <View key={area.id} style={[styles.card, selected && styles.cardSelected]}>
            <TouchableOpacity onPress={() => toggleArea(area.id)} style={styles.headerRow}>
              <Text style={[styles.areaTitle, selected && styles.areaTitleSelected]}>{labelMap[area.id] || area.name}</Text>
              <Text style={[styles.selectText, selected && styles.selectTextSelected]}>{selected ? 'Reviewed' : 'Tap to review'}</Text>
            </TouchableOpacity>
            {selected ? <Text style={styles.areaText}>{area.findings}</Text> : null}
          </View>
        );
      })}

      <TouchableOpacity style={styles.continueButton} onPress={handleContinue}>
        <Text style={styles.continueText}>Continue to Clinical Reasoning</Text>
      </TouchableOpacity>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: COLORS.background },
  content: { padding: SIZES.padding, paddingBottom: 30 },
  title: { fontSize: 24, fontWeight: '700', color: COLORS.text, marginBottom: 8 },
  subtitle: { color: COLORS.muted, marginBottom: 18 },
  card: {
    backgroundColor: COLORS.card,
    borderRadius: SIZES.radius,
    padding: SIZES.padding,
    marginBottom: 14,
    borderWidth: 1,
    borderColor: '#E0E0E0'
  },
  cardSelected: {
    borderColor: COLORS.primary,
    backgroundColor: '#E8F5EF'
  },
  headerRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  areaTitle: { fontSize: 16, fontWeight: '700', color: COLORS.text },
  areaTitleSelected: { color: COLORS.primary },
  selectText: { color: COLORS.muted },
  selectTextSelected: { color: COLORS.primary, fontWeight: '700' },
  areaText: { color: COLORS.muted, marginTop: 12, lineHeight: 22 },
  continueButton: {
    backgroundColor: COLORS.primary,
    borderRadius: 18,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 10
  },
  continueText: { color: COLORS.white, fontWeight: '700' }
});

export default ExaminationScreen;
